3.91 Integrating Generative AI Into DevOps Pipelines
Define a function that truncates text to the maximum length.
Define another function that sanitizes the input by stripping backticks.
const MAX_TITLE_CHARS = 200;
const MAX_BODY_CHARS = 1200;
function truncate(str, max) {
if (!str) return '';
const s = String(str);
return s.length > max ? s.slice(0, max) + '...[truncated]' : s;
}
function sanitize(str) {
if (!str) return '';
return String(str).replace(/```/g, '`');
}
